<script setup lang="ts">
import { computed, ref } from 'vue';
import PublicLayout from '@/layouts/PublicLayout.vue';
import ContentCarousel from '@/components/ContentCarousel.vue';
import MotionCard from '@/components/MotionCard.vue';
import PublicationImage from '@/components/PublicationImage.vue';
import ApiAlert from '@/components/ApiAlert.vue';
import ContentSearch from '@/components/ContentSearch.vue';
import PaginationControls from '@/components/PaginationControls.vue';
import { usePublicContent } from '@/composables/usePublicContent';
import { useAuth } from '@/stores/auth';
import type { ContentKind } from '@/utils/content';
import type { Post } from '@/types/api';
const props = defineProps<{ type: ContentKind }>();
const period = ref<'upcoming' | 'past' | 'all'>('upcoming');
const { posts, pagination, page, search, loading, error, load } = usePublicContent(() => props.type, 9, () => ({ period: period.value }));
const { user } = useAuth();
const view = ref<'list' | 'calendar' | 'carousel'>('list');
const groups = computed(() => {
  const result = new Map<string, { label: string; firstDay: number; days: number; events: Post[] }>();
  for (const event of posts.value) {
    if (!event.eventDate) continue;
    const date = new Date(event.eventDate), year = date.getFullYear(), month = date.getMonth();
    const key = `${year}-${month}`;
    if (!result.has(key)) result.set(key, { label: date.toLocaleDateString('en-US', { month: 'long', year: 'numeric' }), firstDay: new Date(year, month, 1).getDay(), days: new Date(year, month + 1, 0).getDate(), events: [] });
    result.get(key)!.events.push(event);
  }
  return [...result.values()];
});
const part = (value: string | null | undefined, field: 'day' | 'month') => value ? new Date(value).toLocaleDateString('en-US', field === 'day' ? { day: '2-digit' } : { month: 'short' }) : '';
const time = (event: Post) => event.eventTime || (event.eventDate ? new Date(event.eventDate).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' }) : '');
</script>
<template><PublicLayout><div class="reference-ui max-w-7xl mx-auto px-6 py-12">
<section class="mb-12"><div class="flex flex-col md:flex-row md:items-end justify-between gap-6"><div><span class="font-label-sm text-primary-container uppercase tracking-widest">Academic Calendar</span><h1 class="font-h1 text-primary mt-2">{{ period === 'upcoming' ? 'Upcoming Events' : period === 'past' ? 'Past Events' : 'School Events' }}</h1><p class="font-body-md text-secondary mt-4 max-w-2xl">Stay connected with our school community. Find published ceremonies, alumni reunions and school events.</p><RouterLink v-if="user?.role === 'ADMIN'" to="/admin/content/events" class="inline-block mt-4 underline">Manage events</RouterLink></div><div class="flex flex-wrap gap-2 bg-surface-container p-1 rounded-lg" role="group" aria-label="Event display"><button v-for="mode in (['list', 'calendar', 'carousel'] as const)" :key="mode" :aria-pressed="view === mode" :class="['px-4 py-2 font-label-sm flex items-center gap-2', view === mode ? 'bg-white shadow-sm text-primary' : 'text-secondary hover:bg-white/50']" @click="view = mode"><span aria-hidden="true" class="material-symbols-outlined text-lg">{{ mode === 'list' ? 'view_list' : mode === 'calendar' ? 'calendar_month' : 'view_carousel' }}</span>{{ mode === 'list' ? 'List View' : mode === 'calendar' ? 'Calendar View' : 'Carousel View' }}</button></div></div></section>
<div class="grid grid-cols-1 lg:grid-cols-12 gap-8"><aside class="lg:col-span-3 space-y-8"><section class="bg-white border border-outline-variant p-6"><h2 class="font-label-sm text-primary uppercase tracking-wider mb-4">Find an event</h2><label for="event-period" class="field-label">Event dates</label><select id="event-period" v-model="period" class="field-input mb-6"><option value="upcoming">Upcoming events</option><option value="past">Past events</option><option value="all">All published events</option></select><ContentSearch v-model="search" label="Search events" :busy="loading" @search="load()"/><p class="text-xs text-secondary mt-4">Search title or description. Event-type categories are not currently available.</p></section><section class="bg-primary p-6 text-white space-y-4"><span class="font-caption uppercase tracking-widest text-primary-fixed">Notice Board</span><h2 class="font-h2 text-lg">School updates</h2><p class="text-sm text-slate-300">Read published notices for additional information from the school.</p><RouterLink to="/announcements" class="inline-block border border-white px-4 py-2 text-xs font-bold uppercase hover:bg-white hover:text-primary">View announcements</RouterLink></section><p class="font-caption text-secondary">Browse published upcoming events or look back at past events. Registration and ticketing are not offered through this portal.</p></aside>
<section class="lg:col-span-9 min-w-0 space-y-6" aria-label="Published events" :aria-busy="loading"><ApiAlert :message="error"/><button v-if="error" class="secondary-button" @click="load(page)">Retry events</button><p v-if="loading" role="status">Loading published events…</p><template v-else><p v-if="!posts.length && !error" class="border border-outline-variant bg-white p-8">No {{ period === 'all' ? '' : period }} published events found.</p><p v-if="view === 'calendar' && posts.length" class="text-sm text-secondary">Calendar shows events from this results page. Use pagination below to see more.</p>
<ContentCarousel v-if="view === 'carousel' && posts.length" :items="posts" :label="`${period} published events`" :per-view="2"><template #default="{ item: event, index }"><MotionCard :index="index" class="h-full"><article class="h-full border border-outline-variant bg-white"><PublicationImage :src="event.image" fit="contain" class="aspect-video" /><div class="p-6 space-y-4"><time v-if="event.eventDate" :datetime="event.eventDate" class="font-label-sm text-primary">{{ new Date(event.eventDate).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' }) }}</time><h2 class="font-h2 text-primary">{{ event.title }}</h2><p class="font-body-md text-secondary line-clamp-3">{{ event.content }}</p><p v-if="event.eventLocation" class="text-sm text-secondary">{{ event.eventLocation }}</p><RouterLink :to="`/events/${event.id}`" class="inline-block font-label-sm text-primary underline">View Details<span class="sr-only">: {{ event.title }}</span></RouterLink></div></article></MotionCard></template></ContentCarousel>
<template v-if="view !== 'carousel'"><section v-for="group in groups" :key="group.label" class="space-y-4"><h2 class="font-label-sm text-primary uppercase tracking-widest border-b border-outline-variant pb-4">{{ group.label }}</h2><template v-if="view === 'list'"><article v-for="event in group.events" :key="event.id" class="bg-white border border-outline-variant flex flex-col md:flex-row hover:border-primary group"><time :datetime="event.eventDate!" class="md:w-32 bg-primary-container flex md:flex-col items-center justify-center gap-2 p-4 text-white shrink-0"><span class="font-h2">{{ part(event.eventDate, 'day') }}</span><span class="font-label-sm uppercase tracking-widest text-[10px]">{{ part(event.eventDate, 'month') }}</span></time><div class="flex-1 min-w-0 p-6 flex flex-col md:flex-row justify-between items-start md:items-center gap-6"><div><span v-if="event.audience" class="inline-block px-2 py-1 bg-surface-container text-primary text-[10px] font-bold uppercase tracking-widest mb-2">{{ event.audience }}</span><h3 class="font-h2 text-primary">{{ event.title }}</h3><div class="mt-3 space-y-1 text-secondary text-sm"><p class="flex items-center gap-2"><span aria-hidden="true" class="material-symbols-outlined text-lg">schedule</span>{{ time(event) }}</p><p v-if="event.eventLocation" class="flex items-center gap-2"><span aria-hidden="true" class="material-symbols-outlined text-lg">location_on</span>{{ event.eventLocation }}</p></div></div><RouterLink :to="`/events/${event.id}`" class="shrink-0 border border-primary text-primary px-6 py-2 font-bold text-xs uppercase tracking-widest hover:bg-primary hover:text-white">View Details<span class="sr-only">: {{ event.title }}</span></RouterLink></div></article></template>
<div v-else class="overflow-x-auto border border-outline-variant bg-white" role="region" :aria-label="`${group.label} calendar`" tabindex="0"><div class="min-w-[560px]"><div class="grid grid-cols-7 bg-surface-container-low"><span v-for="day in ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']" :key="day" class="p-3 text-xs font-semibold">{{ day }}</span></div><div class="grid grid-cols-7"><div v-for="blank in group.firstDay" :key="`blank-${blank}`" class="border-t border-r border-outline-variant bg-surface-container-low" aria-hidden="true"></div><div v-for="day in group.days" :key="day" class="min-h-24 min-w-0 border-t border-r border-outline-variant p-2"><span class="text-xs text-secondary">{{ day }}</span><RouterLink v-for="event in group.events.filter(event => new Date(event.eventDate!).getDate() === day)" :key="event.id" :to="`/events/${event.id}`" class="mt-2 block bg-primary p-2 text-xs text-white hover:underline">{{ event.title }}</RouterLink></div></div></div></div>
</section></template></template><PaginationControls :page="page" :pagination="pagination" :busy="loading" @change="load"/></section></div>
</div></PublicLayout></template>
